module.header:
extern pdm_instance_t const ${module.driver.pdm.name};
extern pdm_instance_ctrl_t ${module.driver.pdm.name}_ctrl;
extern pdm_cfg_t const ${module.driver.pdm.name}_cfg;
#ifndef ${module.driver.pdm.p_callback}
void ${module.driver.pdm.p_callback}(pdm_callback_args_t * p_args);
#endif
#ifndef ${module.driver.pdm.p_coefficients}
extern pdm_coefficients_t const ${module.driver.pdm.p_coefficients};
#endif

guard.header:
BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_open_guard(pdm_ctrl_t * const p_ctrl, pdm_cfg_t const * const p_cfg);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_start_guard(pdm_ctrl_t * const p_ctrl, uint32_t * const p_buffer, uint32_t const samples);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_stop_guard(pdm_ctrl_t * const p_ctrl);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_status_get_guard(pdm_ctrl_t * const p_ctrl, pdm_status_t * const p_status);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_close_guard(pdm_ctrl_t * const p_ctrl);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_callback_set_guard(pdm_ctrl_t * const p_ctrl, void (* p_callback)(pdm_callback_args_t *), void const * const p_context, pdm_callback_args_t * const p_callback_memory);

guard.template:
#include "guard.h"

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_open_guard(pdm_ctrl_t * const p_ctrl, pdm_cfg_t const * const p_cfg)
{
    FSP_PARAMETER_NOT_USED(p_ctrl);
    FSP_PARAMETER_NOT_USED(p_cfg);
    return R_PDM_Open(&${module.driver.pdm.name}_ctrl, &${module.driver.pdm.name}_cfg);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_start_guard(pdm_ctrl_t * const p_ctrl, uint32_t * const p_buffer, uint32_t const samples)
{
    FSP_PARAMETER_NOT_USED(p_ctrl);
    FSP_ERROR_RETURN((samples > 0U) && (samples <= UINT32_MAX / sizeof(uint32_t)), FSP_ERR_INVALID_SIZE);
    FSP_ERROR_RETURN(NULL != cmse_check_address_range(p_buffer, samples * sizeof(uint32_t), CMSE_AU_NONSECURE | CMSE_MPU_READWRITE), FSP_ERR_INVALID_ADDRESS);
    return R_PDM_Start(&${module.driver.pdm.name}_ctrl, p_buffer, samples);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_stop_guard(pdm_ctrl_t * const p_ctrl)
{
    FSP_PARAMETER_NOT_USED(p_ctrl);
    return R_PDM_Stop(&${module.driver.pdm.name}_ctrl);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_status_get_guard(pdm_ctrl_t * const p_ctrl, pdm_status_t * const p_status)
{
    FSP_PARAMETER_NOT_USED(p_ctrl);
    FSP_ERROR_RETURN(NULL != cmse_check_pointed_object(p_status, CMSE_AU_NONSECURE | CMSE_MPU_READWRITE), FSP_ERR_INVALID_ADDRESS);
    return R_PDM_StatusGet(&${module.driver.pdm.name}_ctrl, p_status);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_close_guard(pdm_ctrl_t * const p_ctrl)
{
    FSP_PARAMETER_NOT_USED(p_ctrl);
    return R_PDM_Close(&${module.driver.pdm.name}_ctrl);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_callback_set_guard(pdm_ctrl_t * const p_ctrl, void (* p_callback)(pdm_callback_args_t *), void const * const p_context, pdm_callback_args_t * const p_callback_memory)
{
    FSP_PARAMETER_NOT_USED(p_ctrl);
    FSP_ERROR_RETURN(NULL != cmse_check_address_range((void *) p_callback, sizeof(void *), CMSE_AU_NONSECURE), FSP_ERR_INVALID_ADDRESS);
    FSP_ERROR_RETURN(NULL != cmse_check_pointed_object(p_callback_memory, CMSE_AU_NONSECURE | CMSE_MPU_READWRITE), FSP_ERR_NO_CALLBACK_MEMORY);
    return R_PDM_CallbackSet(&${module.driver.pdm.name}_ctrl, p_callback, p_context, p_callback_memory);
}

nsc.header:
#define FSP_GUARD_${module.driver.pdm.name}_R_PDM_Open() ${module.driver.pdm.name}_open_guard(FSP_SECURE_ARGUMENT, FSP_SECURE_ARGUMENT)

#define FSP_GUARD_${module.driver.pdm.name}_R_PDM_Start(p_buffer, samples) ${module.driver.pdm.name}_start_guard(FSP_SECURE_ARGUMENT, p_buffer, samples)

#define FSP_GUARD_${module.driver.pdm.name}_R_PDM_Stop() ${module.driver.pdm.name}_stop_guard(FSP_SECURE_ARGUMENT)

#define FSP_GUARD_${module.driver.pdm.name}_R_PDM_StatusGet(p_status) ${module.driver.pdm.name}_status_get_guard(FSP_SECURE_ARGUMENT, p_status)

#define FSP_GUARD_${module.driver.pdm.name}_R_PDM_Close() ${module.driver.pdm.name}_close_guard(FSP_SECURE_ARGUMENT)

#define FSP_GUARD_${module.driver.pdm.name}_R_PDM_CallbackSet(p_callback, p_context, p_callback_memory) ${module.driver.pdm.name}_callback_set_guard(FSP_SECURE_ARGUMENT, p_callback, p_context, p_callback_memory)

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_open_guard(pdm_ctrl_t * const p_ctrl, pdm_cfg_t const * const p_cfg);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_start_guard(pdm_ctrl_t * const p_ctrl, uint32_t * const p_buffer, uint32_t const samples);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_stop_guard(pdm_ctrl_t * const p_ctrl);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_status_get_guard(pdm_ctrl_t * const p_ctrl, pdm_status_t * const p_status);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_close_guard(pdm_ctrl_t * const p_ctrl);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.pdm.name}_callback_set_guard(pdm_ctrl_t * const p_ctrl, void (* p_callback)(pdm_callback_args_t *), void const * const p_context, pdm_callback_args_t * const p_callback_memory);

extern pdm_instance_t const ${module.driver.pdm.name};

nsc.declarations:
static pdm_api_t const ${module.driver.pdm.name}_nsc_api =
{
    .open = ${module.driver.pdm.name}_open_guard,
    .start = ${module.driver.pdm.name}_start_guard,
    .stop = ${module.driver.pdm.name}_stop_guard,
    .statusGet = ${module.driver.pdm.name}_status_get_guard,
    .close = ${module.driver.pdm.name}_close_guard,
    .callbackSet = ${module.driver.pdm.name}_callback_set_guard,
};
pdm_instance_t const ${module.driver.pdm.name} = { .p_api = &${module.driver.pdm.name}_nsc_api, .p_ctrl = FSP_SECURE_ARGUMENT, .p_cfg = FSP_SECURE_ARGUMENT };
